using Sahar.Core.Menu;

namespace Sahar.Core.Activities;

/// <summary>
/// The activities' stroke icons (spec 0.13; ActTag / ActCard), with the mockups' hand-drawn wobble baked in by
/// <c>tools/art/wobble_icons.py --activities</c> (the same seeded filter as <see cref="MenuIcons"/>; regenerate with
/// <c>python3 -I tools/art/wobble_icons.py --activities</c>).
/// </summary>
public static class ActivityIcons
{
    /// <summary>The tag's icon for a kind ("" when the tag shows a cover or a screenshot instead).</summary>
    public static string For(ActivityKind k, WeatherAlert? alert) => k switch
    {
        ActivityKind.ClaudeAsk => "bell",
        ActivityKind.ClaudeWorking => "terminal",
        ActivityKind.ClaudeDone => "check",
        ActivityKind.WeatherAlert => alert switch
        {
            WeatherAlert.Wind or WeatherAlert.Storm => "wind",
            WeatherAlert.Heat => "thermo",
            WeatherAlert.Frost => "snow",
            WeatherAlert.Air => "cloud",
            _ => "rain",
        },
        ActivityKind.WeatherToday => "sun",
        ActivityKind.Copy => "copy",
        ActivityKind.CopyDone => "check",
        ActivityKind.Shelf => "stack",
        ActivityKind.Volume => "speaker",
        ActivityKind.BatteryLow => "battery",
        ActivityKind.Charging => "bolt",
        ActivityKind.CameraMic => "camera",
        ActivityKind.Back => "lock",
        ActivityKind.ScreenTime => "hourglass",
        ActivityKind.Timer => "hourglass",
        ActivityKind.Music or ActivityKind.MusicPaused => "notes",
        _ => "",
    };

